class Solution {
    public int fourSumCount(int[] nums1,int[] nums2,int[] nums3,int[] nums4){
        Map<Integer,Integer> counts=new HashMap<>();
        for(int a:nums1)for(int b:nums2)counts.put(a+b,counts.getOrDefault(a+b,0)+1);
        int answer=0;
        for(int c:nums3)for(int d:nums4)answer+=counts.getOrDefault(-c-d,0);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun fourSumCount(nums1:IntArray,nums2:IntArray,nums3:IntArray,nums4:IntArray):Int{
        val counts=hashMapOf<Int,Int>();
        for(a in nums1)for(b in nums2)counts[a+b]=(counts[a+b]?:0)+1;
        var answer=0;
        for(c in nums3)for(d in nums4)answer+=counts[-c-d]?:0;
        return answer
    }
}

code.cpp:
class Solution {
    public: int fourSumCount(vector<int>& nums1,vector<int>& nums2,vector<int>& nums3,vector<int>& nums4){
        unordered_map<int,int> counts;
        for(int a:nums1)for(int b:nums2)++counts[a+b];
        int answer=0;
        for(int c:nums3)for(int d:nums4)answer+=counts[-c-d];
        return answer;
    }
};
